// Журнал / ИИ-секретарь — Node domain service.
// Reads the local screenpipe SQLite archive in read-only mode and exposes
// narrow business routes for the Client. No third-party dependencies.

import { readFile, readdir, stat } from 'node:fs/promises';
import { createServer } from 'node:http';
import { join } from 'node:path';
import { homedir } from 'node:os';
import { DatabaseSync } from 'node:sqlite';

/** @typedef {import('./miniapp-api.js').MiniAppContext} MiniAppContext */
/** @typedef {import('./miniapp-api.js').MiniAppLifecycle} MiniAppLifecycle */

const TZ = Intl.DateTimeFormat().resolvedOptions().timeZone || 'UTC';

const dateFmt = new Intl.DateTimeFormat('en-CA', {
  timeZone: TZ, year: 'numeric', month: '2-digit', day: '2-digit',
});
const timeFmt = new Intl.DateTimeFormat('en-GB', {
  timeZone: TZ, hour: '2-digit', minute: '2-digit', hour12: false,
});
const hourFmt = new Intl.DateTimeFormat('en-GB', {
  timeZone: TZ, hour: '2-digit', hour12: false,
});
const dowFmt = new Intl.DateTimeFormat('ru-RU', {
  timeZone: TZ, weekday: 'long', day: 'numeric', month: 'long',
});

const toLocalDate = (iso) => dateFmt.format(new Date(iso));
const toLocalTime = (iso) => timeFmt.format(new Date(iso));
const toLocalHour = (iso) => Number(hourFmt.format(new Date(iso)));
const toLocalDow = (iso) => dowFmt.format(new Date(iso));

// ---------------------------------------------------------------- data source

async function resolveDatabaseFile() {
  const base = join(homedir(), '.screenpipe', 'storage');
  let entries;
  try {
    entries = await readdir(base, { withFileTypes: true });
  } catch {
    throw new Error('ARCHIVE_MISSING');
  }
  for (const entry of entries) {
    if (!entry.isDirectory()) continue;
    const file = join(base, entry.name, 'index.sqlite');
    try {
      const info = await stat(file);
      if (info.size > 0) return file;
    } catch { /* keep looking */ }
  }
  throw new Error('ARCHIVE_MISSING');
}

