const CATEGORY_RULES = [
  ['Браузер', /^(chrome|browser|firefox|msedge|opera|brave|vivaldi|yandex)/i],
  ['Разработка', /^(code|codex|opencode|goland|cursor|devenv|idea|pycharm|webstorm|notepad\+\+|sublime|omnisharp|git)/i],
