  ['Мессенджер', /(telegram|discord|slack|teams|whatsapp|signal)/i],
  ['Система', /(explorer|csrss|screenpipe-app|applicationframehost|searchhost|shellexperiencehost|startmenuexperiencehost|dwm|svchost|systemsettings|settings)/i],
];

function categorize(appName) {
  if (!appName) return 'Прочее';
  for (const [label, rule] of CATEGORY_RULES) {
    if (rule.test(appName)) return label;
  }
  return 'Прочее';
}

