function prettyApp(appName) {
  if (!appName) return 'Неизвестно';
  const key = appName.toLowerCase();
  if (PRETTY_APP[key]) return PRETTY_APP[key];
  const base = key.replace(/\.exe$/i, '');
  return base.charAt(0).toUpperCase() + base.slice(1);
}

