async function call(path) {
  const port = globalThis.__port;
  const t = performance.now();
  const r = await fetch(`http://127.0.0.1:${port}${path}`);
  const text = await r.text();
  return { status: r.status, ms: performance.now() - t, body: text };
}

function show(label, path, pick) {
  return call(path).then(({ status, ms, body }) => {
    let parsed;
    try { parsed = JSON.parse(body); } catch { parsed = body; }
    const summary = pick ? pick(parsed) : JSON.stringify(parsed).slice(0, 200);
    console.log(`\n### ${label} -> ${status} ${ms.toFixed(0)}ms`);
    console.log(summary);
    return parsed;
  });
}

globalThis.__port = ctx.listen.port;
console.log('port', ctx.listen.port);
