{"content":"import { start } from './miniapps/zhurnal-secretary/miniapp/node/server.mjs';
import { dirname, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

const here = dirname(fileURLToPath(import.meta.url));
const PORT = 39872;
const BASE = `http://127.0.0.1:${PORT}`;

const controller = new AbortController();
const life = await start({
  pluginId: 'zhurnal-secretary',
  pluginRoot: resolve(here, 'miniapps/zhurnal-secretary'),
  dataDir: resolve(here),
  listen: { host: '127.0.0.1', port: PORT },
  signal: controller.signal,
  logger: { info: () => {}, error: (...a) => console.log('[err]', ...a) },
});

async function get(p) {
  const t = performance.now();
  const r = await fetch(BASE + p);
  const b = await r.json().catch(() => null);
  return { status: r.status, ms: performance.now() - t, body: b };
}

